// Data split readiness (docs/CYRUS-PLATFORM.md section 4).
// 1. The table list the split tooling moves is derived from CyrusDb + SQL-only migrations (never hand-kept).
// 2. CYRUS_DATABASE_URL rules. 3. RATCHET: code outside lib/cyrus that reads/writes Cyrus tables through Nxeon's `db`
//    (it would hit the frozen Nxeon copy after the split) may only SHRINK. Route new code through cyrusDb
//    (`import { cyrusDb } from "@/lib/cyrus/db"`). The split is blocked until the baseline is empty.
//    Regenerate after removing call sites: UPDATE_CYRUS_DB_SPLIT_BASELINE=1 npx tsx --test test/cyrus-db-split.test.ts
import { describe, it } from "node:test";
import assert from "node:assert/strict";
import { readFileSync, readdirSync, statSync, writeFileSync } from "node:fs";
import { spawnSync } from "node:child_process";
import path from "node:path";
import { cyrusDatabaseUrl } from "../lib/cyrus/host/db-url";

const ROOT = path.resolve(__dirname, "..");
const BASELINE = path.join(__dirname, "fixtures", "cyrus-db-split-baseline.json");
const DIRECT = /\b(?:db|tx|prisma)\.(?:cyrus[A-Z]\w*|modBuild)\b/g;

function walk(dir: string, out: string[] = []): string[] {
  for (const n of readdirSync(dir)) {
    if (n === "node_modules" || n === ".next") continue;
    const p = path.join(dir, n);
    if (statSync(p).isDirectory()) walk(p, out);
    else if (/\.(ts|tsx)$/.test(n)) out.push(path.relative(ROOT, p).split(path.sep).join("/"));
  }
  return out;
}
export function scanDirect(): Record<string, number> {
  const res: Record<string, number> = {};
  for (const top of ["app", "lib", "worker", "components", "scripts"]) for (const f of walk(path.join(ROOT, top))) {
    if (f.startsWith("lib/cyrus/")) continue;
    const n = (readFileSync(path.join(ROOT, f), "utf8").match(DIRECT) ?? []).length;
    if (n) res[f] = n;
  }
  return res;
}

describe("Cyrus data split", () => {
  it("derives 28+ Cyrus tables from CyrusDb and the SQL-only migrations", async () => {
    const { cyrusTables } = await import(path.join(ROOT, "scripts/cyrus/data-split/tables.mjs"));
    const t: { name: string; source: string }[] = cyrusTables();
    const names = t.map((x) => x.name);
    assert.ok(names.length >= 28, `${names.length}`);
    for (const must of ["ModBuild", "CyrusProject", "CyrusTokenLedger", "CyrusCatalogEntry", "CyrusWebhookOutbox", "CyrusApiIdempotency"]) assert.ok(names.includes(must), must);
    assert.ok(!names.includes("CyrusWebhookReceipt"), "Nxeon-side receiver table stays");
  });
  it("CYRUS_DATABASE_URL: unset or equal to DATABASE_URL = shared; must be postgres://", () => {
    assert.equal(cyrusDatabaseUrl({}), null);
    assert.equal(cyrusDatabaseUrl({ CYRUS_DATABASE_URL: " postgres://a/x ", DATABASE_URL: "postgres://a/x" }), null);
    assert.equal(cyrusDatabaseUrl({ CYRUS_DATABASE_URL: "postgresql://h/cyrus", DATABASE_URL: "postgres://h/nxeon" }), "postgresql://h/cyrus");
    assert.throws(() => cyrusDatabaseUrl({ CYRUS_DATABASE_URL: "mysql://h/c" }));
  });
  it("split.sh refuses identical databases and writing into the Nxeon database", () => {
    const sh = (env: Record<string, string>) => spawnSync("bash", [path.join(ROOT, "scripts/cyrus/data-split/split.sh"), "copy"], { env: { ...process.env, ...env }, encoding: "utf8" });
    assert.match(sh({ CYRUS_SPLIT_SOURCE_URL: "postgres://h/a", CYRUS_SPLIT_TARGET_URL: "postgres://h/a" }).stderr, /same database/);
    assert.match(sh({ CYRUS_SPLIT_SOURCE_URL: "postgres://h/cyrus", CYRUS_SPLIT_TARGET_URL: "postgres://h/nxeon" }).stderr, /INTO the Nxeon database/);
  });
  it("ratchet: direct Cyrus-table access through Nxeon's db outside lib/cyrus only shrinks", () => {
    const now = scanDirect();
    if (process.env.UPDATE_CYRUS_DB_SPLIT_BASELINE === "1") writeFileSync(BASELINE, JSON.stringify(now, null, 2) + "\n");
    const base: Record<string, number> = JSON.parse(readFileSync(BASELINE, "utf8"));
    const grown = Object.entries(now).filter(([f, n]) => n > (base[f] ?? 0)).map(([f, n]) => `${f}: ${base[f] ?? 0} -> ${n}`);
    assert.deepEqual(grown, [], `new direct Cyrus-table access outside lib/cyrus; use cyrusDb from @/lib/cyrus/db:\n${grown.join("\n")}`);
  });
});
