// Resolved lazily: if a circular import is still loading nxeon.ts when this module evaluates, `nxeonHost` is not defined yet.
let current: CyrusHost | null = null;

/** The active host (the Nxeon implementation unless setHost replaced it). */
export const getHost = (): CyrusHost => current ?? nxeonHost;
/** Replace the host (tests, standalone Cyrus). Returns a function that restores the previous host. */
export function setHost(h: CyrusHost): () => void {
  const prev = current;
  current = h;
  return () => { current = prev; };
}
