export async function deleteListingMedia(mediaId: string): R {
  const { user, allowed } = await requireViewer();
  if (!allowed || !user || typeof mediaId !== "string" || !ID_RE.test(mediaId)) return NF;
  const m = await cyrusDb.cyrusModMedia.findUnique({ where: { id: mediaId } });
  if (!m) return NF;
  const page = await cyrusDb.cyrusModPage.findUnique({ where: { id: m.pageId } });
  if (!page || page.userId !== user.id) return NF;
  await db.$transaction([
    cyrusDb.cyrusModMedia.delete({ where: { id: m.id } }),
    cyrusDb.cyrusModListing.updateMany({ where: { pageId: page.id, iconMediaId: m.id }, data: { iconMediaId: null } }),
    cyrusDb.cyrusModListing.updateMany({ where: { pageId: page.id, bannerMediaId: m.id }, data: { bannerMediaId: null } }),
  ]);
  revalidate(page.slug);
  return { ok: true };
}

